package com.wandertrace.exception; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*; @RestControllerAdvice public class ApiExceptionHandler {@ExceptionHandler(NotFoundException.class) ResponseEntity<Map<String,Object>> notFound(NotFoundException e,HttpServletRequest r){return error(HttpStatus.NOT_FOUND,"Memory not found",r);}@ExceptionHandler(Exception.class) ResponseEntity<Map<String,Object>> unexpected(Exception e,HttpServletRequest r){return error(HttpStatus.INTERNAL_SERVER_ERROR,"Something went wrong",r);}private ResponseEntity<Map<String,Object>> error(HttpStatus status,String message,HttpServletRequest request){var body=new LinkedHashMap<String,Object>();body.put("success",false);body.put("data",null);body.put("message",message);body.put("timestamp",Instant.now().toString());body.put("path",request.getRequestURI());return ResponseEntity.status(status).body(body);}}
